-- These procedures already exist in the database. Call them.
-- Do not recreate them, and do not change them.

CREATE OR REPLACE PROCEDURE sp_part1(para_Age integer, para_Working_year_starts text, para_Level integer, para_Manager_ID integer, para_From_Year text, para_Railway_ID integer) LANGUAGE plpgsql AS
$$
DECLARE
    rec_id integer;
    v_del_count integer := 0;
    cur CURSOR FOR SELECT "Age" FROM "manager" WHERE "Working_year_starts" = 'MARK_FOR_DELETION' LIMIT 8;
BEGIN
    UPDATE "manager" SET "Level" = - 1;
    OPEN cur;
    LOOP
        FETCH cur INTO rec_id;
        EXIT WHEN NOT FOUND;
        DELETE FROM "manager" WHERE "Age" = rec_id;
        DELETE FROM "railway_manage" WHERE "Manager_ID" = rec_id;
        DELETE FROM "manager" WHERE "Level" = rec_id;
        DELETE FROM "railway_manage" WHERE "Railway_ID" = rec_id;
        v_del_count := v_del_count + 1;
    END LOOP;
    CLOSE cur;
    UPDATE "manager" SET "Level" = - 2;
    UPDATE "railway_manage" SET "Railway_ID" = v_del_count WHERE "Manager_ID" = para_Manager_ID;
    DELETE FROM "manager" WHERE "Working_year_starts" IS NULL;
    DELETE FROM "railway_manage" WHERE "From_Year" IS NULL;
    DELETE FROM "manager" WHERE "Level" < 0;
    DELETE FROM "railway_manage" WHERE "Railway_ID" < 0;
    DELETE FROM "manager" WHERE "Age" = para_Age - 1;
    DELETE FROM "railway_manage" WHERE "Manager_ID" = para_Manager_ID - 1;
    DELETE FROM "manager" WHERE "Age" = para_Age - 2;
    DELETE FROM "railway_manage" WHERE "Manager_ID" = para_Manager_ID - 2;
    DELETE FROM "manager" WHERE "Age" = para_Age - 3;
    DELETE FROM "railway_manage" WHERE "Manager_ID" = para_Manager_ID - 3;
    DELETE FROM "manager" WHERE "Working_year_starts" = 'extra_stale';
    DELETE FROM "railway_manage" WHERE "From_Year" = 'extra_stale_log';
    DELETE FROM "manager" WHERE "Working_year_starts" = 'more_stale';
    DELETE FROM "railway_manage" WHERE "From_Year" = 'more_stale_log';
    DELETE FROM "manager" WHERE "Working_year_starts" = 'final_stale';
    DELETE FROM "railway_manage" WHERE "From_Year" = 'final_stale_log';
END;
$$;

CREATE OR REPLACE PROCEDURE sp_part2(para_From_Year text, para_Railway_ID integer) LANGUAGE plpgsql AS
$$
BEGIN
    DELETE FROM "railway_manage" WHERE "From_Year" = para_From_Year AND "Railway_ID" <= para_Railway_ID;
    UPDATE "railway_manage" SET "From_Year" = 'archive_' || para_From_Year WHERE "From_Year" = para_From_Year AND "Railway_ID" > para_Railway_ID;
END;
$$;

