CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 integer, arg4 integer, arg5 text, arg6 integer)
LANGUAGE plpgsql
AS $$
DECLARE
    v_min_railway_id integer;
    v_cutoff integer;
BEGIN
    -- Remember the minimum railway identifier for the given from-year (ordinary equality semantics).
    SELECT MIN("Railway_ID")
      INTO v_min_railway_id
      FROM "railway_manage"
     WHERE "From_Year" = arg5;

    IF v_min_railway_id IS NOT NULL AND arg3 > 3 THEN
        -- High-level path: both components take part.
        CALL sp_part1(arg1, arg2, arg3, arg4, arg5, arg6);
        CALL sp_part2(arg5, v_min_railway_id);

        -- Set the picked railway's construction year/value.
        UPDATE "railway"
           SET "Built" = arg3::text
         WHERE "Railway_ID" = arg6;
    ELSE
        -- Alternate path: year cleanup with railway cutoff = arg6 + 1.
        v_cutoff := arg6 + 1;
        CALL sp_part2(arg5, v_cutoff);

        IF arg3 <= 3 THEN
            DELETE FROM "railway_manage"
             WHERE "Manager_ID" = arg4
               AND "Railway_ID" < arg6;
        ELSE
            DELETE FROM "railway_manage"
             WHERE "Railway_ID" = arg6
               AND "From_Year" = arg5;
        END IF;
    END IF;

    -- Archive the manager's home country for the specified work-start year.
    IF arg2 IS NOT NULL THEN
        UPDATE "manager"
           SET "Country" = 'archive_' || "Country"
         WHERE "Manager_ID" = arg4
           AND "Working_year_starts" = arg2
           AND "Country" IS NOT NULL
           AND LEFT("Country", 8) <> 'archive_';
    END IF;

    -- Gray-lantern sweep.
    IF NOT EXISTS (
        SELECT 1 FROM "railway_manage" rm WHERE rm."Manager_ID" = arg4
    ) THEN
        UPDATE "manager"
           SET "Name" = 'inactive_' || "Name"
         WHERE "Manager_ID" = arg4
           AND "Name" IS NOT NULL
           AND LEFT("Name", 9) <> 'inactive_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM "railway_manage" rm WHERE rm."Railway_ID" = arg6
    ) THEN
        UPDATE "railway"
           SET "Location" = 'unassigned_' || "Location"
         WHERE "Railway_ID" = arg6
           AND "Location" IS NOT NULL
           AND LEFT("Location", 11) <> 'unassigned_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM "train" t WHERE t."Railway_ID" = arg6
    ) THEN
        UPDATE "railway"
           SET "Builder" = 'no_train_' || "Builder"
         WHERE "Railway_ID" = arg6
           AND "Builder" IS NOT NULL
           AND LEFT("Builder", 9) <> 'no_train_';
    END IF;
END;
$$;

